<script lang="ts">
  /**
   * Segundo turno Flávio × Lula: simulação de transferência de votos.
   *
   * Isto NÃO é uma pesquisa de 2º turno nem uma previsão. É uma conta
   * aritmética sobre o cenário corrigido de 1º turno, com uma hipótese
   * declarada e ajustável de para onde vai o voto de cada candidatura que
   * fica fora do confronto. Os controles estão à vista para que qualquer
   * pessoa mude a hipótese e veja o efeito. Quando um confronto de 2º turno
   * medido de verdade for aceito pelo funil, ele aparece ao lado, rotulado.
   */
  import { formatNumber, formatSigned } from '../lib/format';
  import { candidateMedia } from '../lib/candidateMedia';
  import type { CorrectionByCandidate, ScenarioRunoff } from '../lib/types';

  export let rows: CorrectionByCandidate[];
  export let runoff: ScenarioRunoff | null = null;

  type GroupId = 'direita' | 'centro' | 'esquerda' | 'unclassified';
  const GROUPS: Array<{ id: GroupId; label: string; hint: string }> = [
    { id: 'direita', label: 'Campo à direita', hint: 'Zema (NOVO), Marçal (PRTB)…' },
    { id: 'centro', label: 'Centro', hint: 'Caiado (PSD), Cury (Avante)…' },
    { id: 'esquerda', label: 'Campo à esquerda', hint: 'Hertz Dias (PSTU), Edmilson (PCB), Samara (UP)…' },
    { id: 'unclassified', label: 'Fora do eixo', hint: 'Renan Santos (Missão), Clariana (DC)…' },
  ];

  /**
   * Hipótese inicial declarada pelo operador (Douglas, 31/08/2026): "pelo lado
   * de Caiado, Zema, Cury e Marçal, a maioria não vota no Lula". Vale como
   * ponto de partida, não como fato; os controles abaixo mudam tudo.
   */
  let toFlavio: Record<GroupId, number> = { direita: 70, centro: 60, esquerda: 10, unclassified: 40 };
  let toLula: Record<GroupId, number> = { direita: 10, centro: 20, esquerda: 70, unclassified: 35 };
  let base: 'corrigido' | 'publicado' = 'corrigido';

  const isFlavio = (row: CorrectionByCandidate) => /FLAVIO|FLÁVIO/i.test(row.label);
  const isLula = (row: CorrectionByCandidate) => /^LULA\b|LULA DA SILVA/i.test(row.label);

  function share(row: CorrectionByCandidate): number {
    return base === 'corrigido' ? (row.lens_mean_corrected_pct ?? row.reference_valid_pct) : row.reference_valid_pct;
  }

  function groupOf(row: CorrectionByCandidate): GroupId {
    if (row.bloc === 'direita' || row.bloc === 'centro' || row.bloc === 'esquerda') return row.bloc;
    return 'unclassified';
  }

  function displayName(id: string, label: string): string {
    return candidateMedia(id, label).displayName;
  }

  $: flavio = rows.find(isFlavio) ?? null;
  $: lula = rows.find(isLula) ?? null;
  $: others = rows.filter((row) => row !== flavio && row !== lula);

  $: transfers = others.map((row) => {
    const g = groupOf(row);
    const pf = Math.max(0, Math.min(100, toFlavio[g]));
    const pl = Math.max(0, Math.min(100 - pf, toLula[g]));
    const s = share(row);
    return { row, group: g, share: s, toFlavio: (s * pf) / 100, toLula: (s * pl) / 100, toBlank: (s * (100 - pf - pl)) / 100 };
  });

  $: flavioBase = flavio ? share(flavio) : 0;
  $: lulaBase = lula ? share(lula) : 0;
  $: flavioTotal = flavioBase + transfers.reduce((acc, t) => acc + t.toFlavio, 0);
  $: lulaTotal = lulaBase + transfers.reduce((acc, t) => acc + t.toLula, 0);
  $: blankTotal = transfers.reduce((acc, t) => acc + t.toBlank, 0);
  $: twoWay = flavioTotal + lulaTotal;
  $: flavioValid = twoWay > 0 ? (flavioTotal / twoWay) * 100 : 0;
  $: lulaValid = twoWay > 0 ? (lulaTotal / twoWay) * 100 : 0;
  $: leader = flavioValid > lulaValid ? 'Flávio Bolsonaro' : lulaValid > flavioValid ? 'Lula' : 'empate';

  const isFlavioPairing = (m: { candidates: Array<{ label: string }> }) => m.candidates.some((c) => /FLAVIO|FLÁVIO/i.test(c.label));
  // Mais recente primeiro; dentro da mesma pesquisa, Flávio × Lula antes dos demais confrontos.
  $: measured = [...(runoff?.measured ?? [])].sort(
    (a, b) => String(b.field_end).localeCompare(String(a.field_end)) || Number(isFlavioPairing(b)) - Number(isFlavioPairing(a)),
  );
  $: headline = measured.find(isFlavioPairing) ?? measured[0] ?? null;
  $: groupTotals = GROUPS.map((g) => ({
    ...g,
    share: transfers.filter((t) => t.group === g.id).reduce((acc, t) => acc + t.share, 0),
    members: transfers.filter((t) => t.group === g.id).map((t) => displayName(t.row.candidate_id, t.row.label)),
  })).filter((g) => g.share > 0);

  function clampLula(g: GroupId): void {
    if (toFlavio[g] + toLula[g] > 100) toLula[g] = 100 - toFlavio[g];
    toLula = { ...toLula };
    toFlavio = { ...toFlavio };
  }
</script>

<section class="runoff-sim" aria-labelledby="runoff-title">
  <header class="section-title-row compact">
    <div>
      <p class="mini-label">2º turno · Flávio Bolsonaro × Lula</p>
      <h2 id="runoff-title">Simulação de transferência de votos</h2>
      <p>
        Conta aritmética sobre o cenário de 1º turno: cada candidatura fora do confronto transfere
        seus votos conforme a hipótese abaixo. <strong>É hipótese ajustável — não é pesquisa nem previsão.</strong>
      </p>
    </div>
  </header>

  {#if !flavio || !lula}
    <p class="inline-note">Flávio Bolsonaro e Lula precisam estar no cenário para simular o confronto.</p>
  {:else}
    <div class="runoff-result" role="status" aria-live="polite">
      <div class="runoff-side flavio">
        <span class="runoff-name">Flávio Bolsonaro</span>
        <strong class="runoff-figure" data-kind="Simulação" data-value={flavioValid}>{formatNumber(flavioValid)}%</strong>
        <small>votos válidos entre os dois · {formatNumber(flavioTotal)}% do total</small>
      </div>
      <div class="runoff-vs" aria-hidden="true">×</div>
      <div class="runoff-side lula">
        <span class="runoff-name">Lula</span>
        <strong class="runoff-figure" data-kind="Simulação" data-value={lulaValid}>{formatNumber(lulaValid)}%</strong>
        <small>votos válidos entre os dois · {formatNumber(lulaTotal)}% do total</small>
      </div>
    </div>
    <p class="runoff-summary">
      Com a hipótese atual, <strong>{leader === 'empate' ? 'empate' : `${leader} à frente`}</strong> por
      {formatNumber(Math.abs(flavioValid - lulaValid))} pontos entre válidos;
      {formatNumber(blankTotal)}% do total viraria branco, nulo ou abstenção.
      Ponto de partida: Flávio {formatNumber(flavioBase)}% e Lula {formatNumber(lulaBase)}% no
      {base === 'corrigido' ? 'cenário corrigido' : 'publicado'} de 1º turno.
    </p>

    <div class="runoff-controls">
      <div class="period-tabs" role="group" aria-label="Base do 1º turno usada na simulação">
        <button type="button" class:active={base === 'corrigido'} aria-pressed={base === 'corrigido'} onclick={() => (base = 'corrigido')}>Base: cenário corrigido</button>
        <button type="button" class:active={base === 'publicado'} aria-pressed={base === 'publicado'} onclick={() => (base = 'publicado')}>Base: publicado</button>
      </div>

      <table class="runoff-table">
        <caption>Hipótese de transferência por campo (o resto vira branco/nulo)</caption>
        <thead>
          <tr><th scope="col">Campo</th><th scope="col" class="num">Votos no 1º turno</th><th scope="col">→ Flávio</th><th scope="col">→ Lula</th><th scope="col" class="num">→ Branco/nulo</th></tr>
        </thead>
        <tbody>
          {#each groupTotals as g}
            <tr>
              <th scope="row">{g.label}<small>{g.members.join(', ')}</small></th>
              <td class="num">{formatNumber(g.share)}%</td>
              <td>
                <label class="runoff-slider">
                  <input type="range" min="0" max="100" step="5" bind:value={toFlavio[g.id]} oninput={() => clampLula(g.id)} aria-label={`Parcela de ${g.label} que vai para Flávio`} />
                  <span>{toFlavio[g.id]}%</span>
                </label>
              </td>
              <td>
                <label class="runoff-slider">
                  <input type="range" min="0" max={100 - toFlavio[g.id]} step="5" bind:value={toLula[g.id]} aria-label={`Parcela de ${g.label} que vai para Lula`} />
                  <span>{toLula[g.id]}%</span>
                </label>
              </td>
              <td class="num">{100 - toFlavio[g.id] - toLula[g.id]}%</td>
            </tr>
          {/each}
        </tbody>
      </table>
      <p class="small muted">
        Ponto de partida declarado pelo operador em 31/08/2026: "pelo lado de Caiado, Zema, Cury e Marçal, a maioria
        não vota no Lula". Mexa nos controles: o resultado acima recalcula na hora. Nada aqui foi medido.
      </p>
    </div>

    <div class="runoff-measured">
      <h3>Confronto medido diretamente pelas casas</h3>
      {#if measured.length && headline}
        <p class="runoff-headline">
          Última medição direta — <strong>{headline.house_name}</strong>, campo até {headline.field_end}
          ({headline.registration_no}):
          {#each headline.candidates.filter((c) => !/branco|nulo|ns\/nr|não sabe|nao sabe/i.test(c.label)) as c, i}{i ? ' × ' : ' '}<strong data-kind="Publicado" data-value={c.published_pct}>{c.label} {formatNumber(c.published_pct)}%</strong>{/each}
          <small>(% do total, como publicado; aceito pelo funil com registro TSE)</small>
        </p>
        <ul>
          {#each measured as m}
            <li>
              <strong>{m.house_name}</strong> · campo até {m.field_end} · {m.registration_no}:
              {#each m.candidates as c, i}{i ? ' · ' : ' '}{c.label} {formatNumber(c.published_pct)}%{/each}
              {#if m.corrected_note}<small> · {m.corrected_note}</small>{/if}
            </li>
          {/each}
        </ul>
      {:else}
        <p class="inline-note">
          <strong>Indisponível.</strong> {runoff?.reason ?? 'Nenhum confronto de 2º turno foi aceito pelo funil até agora.'}
          {#if runoff?.pending}
            {runoff.pending} cenário(s) de 2º turno já capturado(s) aguardam evidência completa; quando validarem, aparecem aqui sozinhos.
          {/if}
        </p>
      {/if}
    </div>
  {/if}
</section>
