<script lang="ts">
  /** Deterministic sentences from automatic_insights.json, each with its rule. */
  import type { AutomaticInsightsPayload } from '../lib/types';

  export let insights: AutomaticInsightsPayload;
  export let limit = 0;

  const strengthLabel: Record<string, string> = {
    insuficiente: 'Evidência insuficiente',
    fraco: 'Evidência fraca',
    moderado: 'Evidência moderada',
    forte: 'Evidência forte',
  };

  $: rows = limit > 0 ? insights.insights.slice(0, limit) : insights.insights;
</script>

<section class="insights-panel" aria-labelledby="insights-title">
  <header class="section-title-row">
    <div>
      <p class="mini-label">Leitura automática</p>
      <h2 id="insights-title">O que os dados dizem agora</h2>
      <p>
        Cada frase é gerada por uma regra determinística sobre os contratos publicados.
        Nenhuma é escrita por modelo de linguagem e nenhuma afirma causa.
      </p>
    </div>
  </header>

  <ul class="insight-list">
    {#each rows as insight}
      <li class={`insight strength-${insight.evidence_strength}`}>
        <p class="insight-headline">{insight.headline}</p>
        <p class="insight-detail">{insight.detail}</p>
        <details>
          <summary>Ver cálculo e dados usados</summary>
          <dl>
            <div><dt>Regra</dt><dd>{insight.rule}</dd></div>
            <div><dt>Nível de evidência</dt><dd>{strengthLabel[insight.evidence_strength]}</dd></div>
            <div><dt>Dados usados</dt><dd>{insight.inputs.join(', ')}</dd></div>
            <div><dt>Run</dt><dd><code>{insight.run_id}</code></dd></div>
          </dl>
          <a href={insight.calculation_ref} data-route>Abrir a página do cálculo</a>
        </details>
      </li>
    {/each}
  </ul>

  <p class="inline-note">{insights.generation.note}</p>
</section>
